const inputPhone = ($('When Called').first().json.phone_number || '').replace(/\D/g, '');
const clients = $input.all();
for (const item of clients) {
  const assigned = (item.json['property_assigned_twilio_number'] || '').replace(/\D/g, '');
  if (assigned && inputPhone && assigned === inputPhone) {
    return [{ json: {
      found: true,
      client_id: item.json.id,
      client_name: item.json['property_client_name'],
      niche: item.json['property_niche'],
      voice_agent_name: item.json['property_voice_agent_name'],
      after_hours_mode: item.json['property_after_hours_mode'],
      booking_method: item.json['property_booking_method'],
      transfer_name: item.json['property_transfer_name'],
      brand_profile_url: item.json['property_brand_profile_url'],
      gbp_place_id: item.json['property_gbp_place_id'],
      assigned_twilio_number: item.json['property_assigned_twilio_number'],
      email: item.json['property_email']
    } }];
  }
}
return [{ json: { found: false, client_id: null, error: 'No client matched Assigned Twilio Number ' + inputPhone } }];
